			w.Header().Set("Link", `<`+foreign.URL+`/v2/x/tags/list?last=a>; rel="next"`)
			_, _ = fmt.Fprint(w, tags)
		}))
		defer srv.Close()

		got, err := ListRegistryTagsContext(context.Background(), srv.URL, "x", "user", "pass")
		if err != nil {
			t.Fatalf("err = %v, want the first page without error", err)
		}
